import type { Metadata } from "next";
import { lens } from "@/content/lens";
import LensHero from "@/components/sections/lens/LensHero";
import LensRankings from "@/components/sections/lens/LensRankings";
import LensHistory from "@/components/sections/lens/LensHistory";
import LensContact from "@/components/sections/lens/LensContact";
import styles from "@/components/sections/lens/Lens.module.css";

export const metadata: Metadata = {
  title: lens.metadata.title,
  description: lens.metadata.description,
  alternates: { canonical: lens.metadata.url },
  openGraph: {
    title: lens.metadata.title,
    description: lens.metadata.description,
    url: lens.metadata.url,
    siteName: "Spotter.ai",
    type: "website",
    images: [
      {
        url: lens.metadata.image,
        width: 1200,
        height: 630,
        alt: lens.ui.productName,
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: lens.metadata.title,
    description: lens.metadata.description,
    images: [lens.metadata.image],
  },
};

export default function LensPage() {
  const schema = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: lens.metadata.title,
    url: lens.metadata.url,
    description: lens.metadata.description,
    about: {
      "@type": "SoftwareApplication",
      name: lens.ui.productName,
      applicationCategory: "BusinessApplication",
      operatingSystem: "Web browser",
    },
  };
  return (
    <main id="main-content" tabIndex={-1} className={styles.page}>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(schema).replace(/</g, "\\u003c"),
        }}
      />
      <LensHero />
      <LensRankings />
      <LensHistory />
      <LensContact />
    </main>
  );
}
